import Link from "next/link";
import { CodeBlock, Footer, Header } from "../components";
import "./chapter-one.css";
import "./chapter-two.css";

type Locale = "en" | "fr";
type Lesson = "overview" | "requete" | "structure" | "mvc" | "variantes" | "atelier";
const order: Lesson[] = ["overview", "requete", "structure", "mvc", "variantes", "atelier"];
const labels = {
  en: { overview: "How a website works", requete: "From browser to page", structure: "Organizing files", mvc: "Sharing the work", variantes: "Choosing a project", atelier: "First guided page" },
  fr: { overview: "Comment fonctionne un site", requete: "Du navigateur à la page", structure: "Ranger les fichiers", mvc: "Partager le travail", variantes: "Choisir un projet", atelier: "Première page guidée" },
};
const descriptions = {
  en: { overview: "Start without technical vocabulary", requete: "Follow one simple address", structure: "Understand the main folders", mvc: "Give each file one job", variantes: "Classic, View, API, or Console", atelier: "Build while understanding each step" },
  fr: { overview: "Commencer sans vocabulaire technique", requete: "Suivre une adresse simple", structure: "Comprendre les dossiers principaux", mvc: "Donner un travail à chaque fichier", variantes: "Classique, View, API ou Console", atelier: "Construire en comprenant chaque étape" },
};

function url(locale: Locale, lesson: Lesson) {
  const prefix = locale === "fr" ? "/fr" : "";
  return lesson === "overview" ? prefix + "/docs/02" : prefix + "/docs/02/" + lesson;
}
function Nav({ locale, current }: { locale: Locale; current: Lesson }) {
  const fr = locale === "fr";
  return <nav className="chapter-one-nav"><div><small>{fr ? "CHAPITRE 02" : "CHAPTER 02"}</small><strong>{fr ? "Architecture" : "Architecture"}</strong></div><ol>{order.map((item, index) => <li key={item} className={item === current ? "active" : ""}><Link href={url(locale, item)}><span>{String(index + 1).padStart(2, "0")}</span><div><strong>{labels[locale][item]}</strong><small>{descriptions[locale][item]}</small></div></Link></li>)}</ol></nav>;
}
function Pager({ locale, current }: { locale: Locale; current: Lesson }) {
  const index = order.indexOf(current);
  const previous = order[index - 1];
  const next = order[index + 1];
  return <nav className="chapter-one-pager"><Link href={previous ? url(locale, previous) : (locale === "fr" ? "/fr/docs/01" : "/docs/01")}>← {previous ? labels[locale][previous] : (locale === "fr" ? "Chapitre 01" : "Chapter 01")}</Link><Link href={next ? url(locale, next) : (locale === "fr" ? "/fr/docs/reference#migration" : "/docs/reference#migration")}>{next ? labels[locale][next] : (locale === "fr" ? "Chapitre 03" : "Chapter 03")} →</Link></nav>;
}
function Frame({ locale, lesson, title, intro, children }: { locale: Locale; lesson: Lesson; title: React.ReactNode; intro: string; children: React.ReactNode }) {
  const fr = locale === "fr";
  return <><Header locale={locale} path="/docs/02"/><main className="chapter-one-page"><header className="chapter-one-hero shell"><p className="eyebrow"><span/> {fr ? "Documentation · Chapitre 02" : "Documentation · Chapter 02"}</p><h1>{title}</h1><p>{intro}</p><p className="chapter-two-audience">{fr ? "Aucun vocabulaire technique préalable n’est nécessaire. Chaque nouveau mot est expliqué avant d’être utilisé." : "No prior technical vocabulary is required. Every new word is explained before it is used."}</p></header><div className="chapter-one-layout shell"><Nav locale={locale} current={lesson}/><article className="chapter-one-article">{children}<Pager locale={locale} current={lesson}/></article></div></main><Footer locale={locale}/></>;
}

export function ChapterTwoPage({ locale, lesson }: { locale: Locale; lesson: Lesson }) {
  const fr = locale === "fr";
  if (lesson === "overview") return <Frame locale={locale} lesson={lesson} title={fr ? <>Comment fonctionne<br/><em>un site Web ?</em></> : <>How does<br/><em>a website work?</em></>} intro={fr ? "Partons de zéro. Avant de parler de PHPAML, observons simplement ce qui se passe lorsque vous ouvrez une page dans votre navigateur." : "Let us start from zero. Before discussing PHPAML, we will simply observe what happens when you open a page in your browser."}>
    <section className="chapter-one-lead"><span>≈ 55 min</span><h2>{fr ? "Vous connaissez déjà le début de l’histoire." : "You already know how the story begins."}</h2><p>{fr ? "Vous ouvrez Chrome, Safari ou Firefox. Vous écrivez une adresse, par exemple phpaml.com, puis vous appuyez sur Entrée. Quelques instants plus tard, une page apparaît. Ce chapitre explique ce voyage sans supposer que vous savez déjà programmer." : "You open Chrome, Safari, or Firefox. You type an address, such as phpaml.com, then press Enter. A page appears moments later. This chapter explains that journey without assuming you already know how to program."}</p></section>
    <section><h2>{fr ? "Deux ordinateurs se parlent." : "Two computers talk to each other."}</h2><div className="beginner-dialogue"><div><span>1</span><strong>{fr ? "Votre navigateur demande" : "Your browser asks"}</strong><p>{fr ? "« Peux-tu me donner la page du livre numéro 12 ? »" : "“Can you give me the page for book number 12?”"}</p></div><div><span>2</span><strong>{fr ? "Le serveur répond" : "The server answers"}</strong><p>{fr ? "« Oui. Voici le titre, l’auteur, l’image et la mise en page. »" : "“Yes. Here are the title, author, image, and page layout.”"}</p></div></div><p>{fr ? "Le navigateur est le programme que vous utilisez pour visiter le Web. Le serveur est l’ordinateur qui exécute l’application PHPAML et prépare la réponse. Même lorsqu’ils fonctionnent sur votre propre Mac avec 127.0.0.1, ces deux rôles restent distincts." : "The browser is the program you use to visit the Web. The server is the computer that runs the PHPAML application and prepares the answer. Even when both run on your own Mac at 127.0.0.1, these roles remain separate."}</p></section>
    <Vocabulary fr={fr} items={fr ? [["Navigateur", "Le programme qui affiche les sites Web : Chrome, Safari ou Firefox."], ["Serveur", "Le programme ou l’ordinateur qui reçoit une demande et prépare une réponse."], ["Application", "L’ensemble des fichiers qui produisent le comportement du site."], ["Code", "Les instructions écrites par le développeur pour dire à l’application quoi faire."]] : [["Browser", "The program that displays websites: Chrome, Safari, or Firefox."], ["Server", "The program or computer that receives a request and prepares an answer."], ["Application", "The collection of files that produces the website's behavior."], ["Code", "Instructions written by a developer to tell the application what to do."]]}/>
    <section><h2>{fr ? "Où interviennent PHP et PHPAML ?" : "Where do PHP and PHPAML enter the picture?"}</h2><p>{fr ? "PHP est le langage dans lequel vous écrivez les instructions exécutées par le serveur. Le navigateur ne lit pas directement vos classes PHP : le serveur exécute PHP, construit une réponse, puis envoie au navigateur un résultat qu’il sait afficher." : "PHP is the language used to write instructions executed by the server. The browser does not directly read your PHP classes: the server runs PHP, builds an answer, then sends the browser a result it can display."}</p><p>{fr ? "PHPAML ajoute une organisation et des outils autour de PHP. Il démarre le serveur avec aml serve, reconnaît les adresses de vos pages, charge le bon code, protège les échanges courants et facilite plusieurs types de projets. Votre logique reste écrite en PHP." : "PHPAML adds organization and tools around PHP. It starts the server with aml serve, recognizes your page addresses, loads the right code, protects common exchanges, and supports several project types. Your logic remains written in PHP."}</p><div className="good-bad"><div><span>PHP</span><p>{fr ? "Le langage : variables, conditions, fonctions, classes et objets." : "The language: variables, conditions, functions, classes, and objects."}</p></div><div><span>PHPAML</span><p>{fr ? "Le cadre de travail : démarrage, dossiers, routes, réponses et outils de développement." : "The working framework: startup, folders, routes, responses, and development tools."}</p></div></div></section>
    <section><h2>{fr ? "Que reçoit réellement le navigateur ?" : "What does the browser actually receive?"}</h2><p>{fr ? "Une page Web complète utilise généralement plusieurs types de fichiers. PHP prépare le contenu dynamique sur le serveur; le navigateur assemble ensuite les éléments reçus." : "A complete Web page generally uses several file types. PHP prepares dynamic content on the server; the browser then assembles the received elements."}</p><div className="useful-grid"><InfoCard title="HTML" text={fr ? "La structure et le contenu : titres, paragraphes, liens et formulaires." : "Structure and content: headings, paragraphs, links, and forms."}/><InfoCard title="CSS" text={fr ? "L’apparence : couleurs, espacements, tailles et disposition." : "Appearance: colors, spacing, sizes, and layout."}/><InfoCard title={fr ? "Images et médias" : "Images and media"} text={fr ? "Les fichiers visuels ou sonores chargés par la page." : "Visual or audio files loaded by the page."}/><InfoCard title="JavaScript" text={fr ? "Les comportements exécutés dans le navigateur lorsqu’ils sont nécessaires. AML View peut en générer sans que vous l’écriviez manuellement." : "Behavior executed in the browser when needed. AML View can generate it without requiring you to write it manually."}/></div></section>
    <BeginnerQuestions fr={fr} items={fr ? [["Est-ce que mon navigateur exécute PHP ?", "Non. PHP s’exécute côté serveur. Le navigateur reçoit le résultat produit."], ["Pourquoi 127.0.0.1 fonctionne sans Internet ?", "Cette adresse désigne votre propre ordinateur. Votre navigateur parle au serveur lancé localement par AML."], ["Dois-je tout comprendre immédiatement ?", "Non. Retenez d’abord le dialogue navigateur–serveur. Les noms précis viendront progressivement."]] : [["Does my browser run PHP?", "No. PHP runs on the server. The browser receives the produced result."], ["Why does 127.0.0.1 work without the Internet?", "This address points to your own computer. Your browser talks to the server started locally by AML."], ["Must I understand everything immediately?", "No. First remember the browser–server conversation. Precise names will come gradually."]]}/>
    <Analogy fr={fr} title={fr ? "Imaginez un restaurant." : "Imagine a restaurant."}>{fr ? "Vous dites au serveur ce que vous souhaitez. Vous n’avez pas besoin de connaître l’emplacement du réfrigérateur ni la recette. Plusieurs personnes travaillent derrière la scène, chacune avec un rôle simple. PHPAML organise un site de la même façon. Nous donnerons un nom à chaque rôle seulement lorsque nous en aurons besoin." : "You tell the waiter what you want. You do not need to know where the refrigerator is or how the recipe works. Several people work behind the scenes, each with one simple role. PHPAML organizes a website in the same way. We will name each role only when we need it."}</Analogy>
    <RunningExample fr={fr}/>
    <section><h2>{fr ? "Le voyage en quatre actions simples." : "The journey in four simple actions."}</h2><div className="architecture-flow"><Box n="1" title={fr ? "Demander" : "Ask"} text={fr ? "le livre 12" : "for book 12"}/><b>→</b><Box n="2" title={fr ? "Diriger" : "Direct"} text={fr ? "vers le bon code" : "to the right code"}/><b>→</b><Box n="3" title={fr ? "Préparer" : "Prepare"} text={fr ? "le livre demandé" : "the requested book"}/><b>→</b><Box n="4" title={fr ? "Afficher" : "Display"} text={fr ? "la page terminée" : "the finished page"}/></div><p>{fr ? "En programmation, ces actions portent des noms précis : requête, route, contrôleur et réponse. Ne les mémorisez pas encore. Les pages suivantes les introduisent une par une avec le même exemple." : "In programming, these actions have precise names: request, route, controller, and response. Do not memorize them yet. The next pages introduce them one at a time using the same example."}</p></section>
    <section><h2>{fr ? "À la fin, vous saurez répondre à quatre questions." : "By the end, you will answer four questions."}</h2><ul className="chapter-two-goals"><li>{fr ? "Que se passe-t-il après avoir écrit une adresse Web ?" : "What happens after typing a Web address?"}</li><li>{fr ? "Pourquoi un projet contient-il plusieurs dossiers ?" : "Why does a project contain several folders?"}</li><li>{fr ? "Pourquoi ne met-on pas tout le code au même endroit ?" : "Why do we not put all code in one place?"}</li><li>{fr ? "Quel type de projet PHPAML choisir ?" : "Which PHPAML project type should you choose?"}</li></ul></section>
    <MiniExercise fr={fr} prompt={fr ? "Pour une page /books/12, écrivez sur papier les quatre stations traversées avant l’affichage du titre du livre." : "For a /books/12 page, write down the four stations crossed before the book title appears."} hint={fr ? "Commencez par : requête → route → …" : "Start with: request → route → …"}/>
    <Summary fr={fr} points={fr ? ["Le navigateur demande une page.", "Le serveur prépare puis renvoie cette page.", "Un projet utilise plusieurs étapes pour organiser ce travail.", "La suite expliquera chaque étape avec le même livre numéro 12."] : ["The browser asks for a page.", "The server prepares and returns that page.", "A project uses several steps to organize this work.", "The rest of the chapter explains each step using the same book number 12."]}/>
  </Frame>;

  if (lesson === "requete") return <Frame locale={locale} lesson={lesson} title={fr ? <>Que se passe-t-il<br/><em>après Entrée ?</em></> : <>What happens<br/><em>after Enter?</em></>} intro={fr ? "Vous écrivez une adresse dans le navigateur. Suivons maintenant la demande jusqu’à la page qui apparaît." : "You type an address in the browser. Now let us follow the request until the page appears."}>
    <RunningExample fr={fr}/>
    <section><p className="chapter-one-kicker">{fr ? "PREMIER NOUVEAU MOT" : "FIRST NEW WORD"}</p><h2>{fr ? "Une demande s’appelle une requête." : "A request is called a request."}</h2><p>{fr ? "Lorsque le navigateur demande une page au serveur, les développeurs appellent ce message une requête. Elle contient principalement l’action souhaitée et l’adresse demandée." : "When the browser asks the server for a page, developers call that message a request. It mainly contains the desired action and requested address."}</p><CodeBlock>{"GET /books/12"}</CodeBlock><div className="code-decoder"><div><code>GET</code><p>{fr ? "signifie simplement : « donne-moi cette information »" : "simply means: “give me this information”"}</p></div><div><code>/books/12</code><p>{fr ? "est la partie de l’adresse qui désigne le livre numéro 12" : "is the part of the address that identifies book number 12"}</p></div></div><p>{fr ? "HTTP est le nom des règles communes utilisées par les navigateurs et les serveurs pour se parler. Vous n’avez pas à écrire ces messages à la main : le navigateur le fait pour vous." : "HTTP is the name of the shared rules browsers and servers use to communicate. You do not write these messages manually: the browser does it for you."}</p></section>
    <section><h2>{fr ? "La demande traverse plusieurs postes." : "The request crosses several stations."}</h2><p>{fr ? "Comme une lettre passe par plusieurs mains avant d’arriver au bon service, la requête avance étape par étape. Chaque poste répond à une question simple." : "Like a letter passing through several hands before reaching the right department, the request moves one step at a time. Each station answers one simple question."}</p><ol className="request-steps"><Step n="1" title={fr ? "Entrée de l’application" : "Application entrance"}>{fr ? "Une demande vient-elle d’arriver ? PHPAML démarre le projet." : "Has a request arrived? PHPAML starts the project."}</Step><Step n="2" title={fr ? "Contrôles de sécurité" : "Security checks"}>{fr ? "Cette personne a-t-elle le droit de continuer ?" : "Is this person allowed to continue?"}</Step><Step n="3" title={fr ? "Route" : "Route"}>{fr ? "Quel code sait traiter l’adresse /books/12 ? Une route est simplement une règle qui relie une adresse à une action." : "Which code can handle /books/12? A route is simply a rule connecting an address to an action."}</Step><Step n="4" title={fr ? "Contrôleur" : "Controller"}>{fr ? "Que faut-il faire pour obtenir le livre ? Le contrôleur organise le travail." : "What must happen to obtain the book? The controller organizes the work."}</Step><Step n="5" title={fr ? "Données et présentation" : "Data and presentation"}>{fr ? "Quel est le livre et comment doit-il apparaître ?" : "Which book is it, and how should it appear?"}</Step><Step n="6" title={fr ? "Réponse" : "Response"}>{fr ? "Le serveur renvoie enfin la page terminée au navigateur." : "The server finally sends the completed page back to the browser."}</Step></ol></section>
    <Vocabulary fr={fr} items={fr ? [["Requête", "La demande envoyée par le navigateur."], ["Route", "La règle qui relie une adresse au code chargé de la traiter."], ["Contrôleur", "Le code qui organise les actions nécessaires pour répondre."], ["Réponse", "Le résultat renvoyé au navigateur : une page, des données ou une erreur."]] : [["Request", "The message sent by the browser."], ["Route", "The rule connecting an address to the code that handles it."], ["Controller", "The code that organizes the actions needed to answer."], ["Response", "The result sent to the browser: a page, data, or an error."]]}/>
    <section><h2>{fr ? "Décomposons une adresse complète." : "Let us break down a complete address."}</h2><CodeBlock>{"http://127.0.0.1:8910/books/12"}</CodeBlock><div className="placement-table"><Row left={fr ? "http : la manière de communiquer" : "http: the way to communicate"} right="http://"/><Row left={fr ? "127.0.0.1 : votre propre ordinateur" : "127.0.0.1: your own computer"} right="host"/><Row left={fr ? "8910 : la porte utilisée par aml serve" : "8910: the door used by aml serve"} right="port"/><Row left={fr ? "/books/12 : la ressource demandée" : "/books/12: the requested resource"} right="path"/></div><p>{fr ? "Sur un site public, le nom de domaine remplace généralement 127.0.0.1 et le port n’est pas affiché. Le principe reste identique : l’adresse permet au navigateur de trouver un serveur puis de préciser ce qu’il souhaite." : "On a public website, a domain name generally replaces 127.0.0.1 and the port is hidden. The principle stays the same: the address lets the browser find a server and specify what it wants."}</p></section>
    <section><h2>{fr ? "Une requête peut transporter des informations de trois façons." : "A request can carry information in three ways."}</h2><div className="useful-grid"><InfoCard title={fr ? "Dans le chemin" : "In the path"} text="/books/12 — le nombre 12 identifie le livre."/><InfoCard title={fr ? "Après le signe ?" : "After the ? sign"} text="/books?author=Ada — pratique pour filtrer ou rechercher."/><InfoCard title={fr ? "Dans le contenu envoyé" : "Inside the sent content"} text={fr ? "Un formulaire peut envoyer un nom, un courriel ou un nouveau livre sans les afficher dans l’adresse." : "A form can send a name, email, or new book without displaying it in the address."}/><InfoCard title={fr ? "Dans les en-têtes" : "In headers"} text={fr ? "Des informations complémentaires : format accepté, langue, session ou authentification." : "Additional information: accepted format, language, session, or authentication."}/></div></section>
    <section><h2>{fr ? "Les actions HTTP les plus utiles." : "The most useful HTTP actions."}</h2><div className="placement-table"><Row left={fr ? "Lire une liste ou une page" : "Read a list or page"} right="GET"/><Row left={fr ? "Créer une nouvelle information" : "Create new information"} right="POST"/><Row left={fr ? "Remplacer une information existante" : "Replace existing information"} right="PUT"/><Row left={fr ? "Modifier seulement une partie" : "Modify only one part"} right="PATCH"/><Row left={fr ? "Supprimer une information" : "Delete information"} right="DELETE"/></div><p>{fr ? "Ces mots décrivent l’intention. Une route associe donc une action et un chemin : GET /books ne signifie pas la même chose que POST /books." : "These words describe intent. A route therefore combines an action and a path: GET /books does not mean the same thing as POST /books."}</p></section>
    <section><h2>{fr ? "Lire rapidement les codes de réponse." : "Quickly read response codes."}</h2><div className="status-families"><div><code>2xx</code><p>{fr ? "Le travail a réussi. 200 indique une réponse normale; 201 indique souvent une création réussie." : "The work succeeded. 200 indicates a normal response; 201 often indicates successful creation."}</p></div><div><code>3xx</code><p>{fr ? "Le navigateur doit aller ailleurs. 301 est un déplacement permanent; 302 une redirection temporaire." : "The browser must go elsewhere. 301 is a permanent move; 302 a temporary redirect."}</p></div><div><code>4xx</code><p>{fr ? "La demande ne peut pas être satisfaite : adresse, autorisation, validation ou action incorrecte." : "The request cannot be fulfilled: incorrect address, permission, validation, or action."}</p></div><div><code>5xx</code><p>{fr ? "L’application ou le serveur a rencontré une erreur pendant le traitement." : "The application or server encountered an error while processing."}</p></div></div></section>
    <section><h2>{fr ? "Pourquoi ne pas ouvrir directement un fichier PHP ?" : "Why not open a PHP file directly?"}</h2><p>{fr ? "Parce qu’une adresse publique ne doit pas dépendre de l’emplacement physique du code. La route /books/12 peut évoluer sans exposer src/controllers/BookController.php. Le routeur fournit aussi un seul endroit pour contrôler la méthode HTTP, l’authentification et les paramètres." : "Because a public address should not depend on the physical location of code. The /books/12 route can evolve without exposing src/controllers/BookController.php. The router also provides one place to control the HTTP method, authentication, and parameters."}</p><div className="good-bad"><div><span>{fr ? "À ÉVITER" : "AVOID"}</span><code>/src/controllers/book.php?id=12</code><p>{fr ? "L’URL révèle l’organisation interne et couple le navigateur aux fichiers." : "The URL reveals internal organization and couples the browser to files."}</p></div><div><span>{fr ? "À PRÉFÉRER" : "PREFER"}</span><code>/books/12</code><p>{fr ? "L’adresse décrit la ressource, tandis que PHPAML choisit le code interne." : "The address describes the resource while PHPAML selects internal code."}</p></div></div></section>
    <section><h2>{fr ? "Et si quelque chose ne fonctionne pas ?" : "What if something does not work?"}</h2><p>{fr ? "Le serveur renvoie un nombre appelé code d’état. Ce nombre résume le résultat. Vous avez probablement déjà rencontré 404 sur Internet." : "The server sends a number called a status code. This number summarizes the result. You have probably already seen 404 on the Internet."}</p><div className="status-grid"><div><code>404</code><strong>{fr ? "Adresse introuvable" : "Address not found"}</strong><p>{fr ? "L’application ne connaît pas cette adresse." : "The application does not know this address."}</p></div><div><code>405</code><strong>{fr ? "Action refusée" : "Action not allowed"}</strong><p>{fr ? "L’adresse existe, mais pas pour l’action demandée." : "The address exists, but not for the requested action."}</p></div><div><code>500</code><strong>{fr ? "Le code a échoué" : "The code failed"}</strong><p>{fr ? "L’application a commencé le travail, puis une erreur s’est produite." : "The application began working, then an error occurred."}</p></div></div></section>
    <BeginnerQuestions fr={fr} items={fr ? [["Une route est-elle une page ?", "Pas exactement. La route est la règle qui décide quel code répond à une adresse. Ce code peut ensuite construire une page ou renvoyer des données."], ["Pourquoi GET ?", "GET indique que le navigateur veut lire une ressource. D’autres actions existent, comme POST pour envoyer de nouvelles informations."], ["Pourquoi afficher des codes d’erreur ?", "Ils indiquent à quel endroit chercher : adresse inconnue, action interdite ou erreur pendant l’exécution."]] : [["Is a route a page?", "Not exactly. A route is the rule deciding which code answers an address. That code can then build a page or return data."], ["Why GET?", "GET says that the browser wants to read a resource. Other actions exist, such as POST for sending new information."], ["Why show error codes?", "They indicate where to investigate: unknown address, forbidden action, or failure during execution."]]}/>
    <Checkpoint fr={fr} question={fr ? "Une route GET /users existe. Que doit répondre une requête POST /users si aucune route POST n’est déclarée ?" : "A GET /users route exists. What should POST /users return when no POST route is declared?"} answer="405 Method Not Allowed"/>
    <MiniExercise fr={fr} prompt={fr ? "Classez ces problèmes : /books/12 inconnu, contrôleur qui lance une exception, route accessible seulement en POST." : "Classify these problems: unknown /books/12, controller throwing an exception, route available only through POST."} hint={fr ? "Réponses attendues : 404, 500 et 405." : "Expected answers: 404, 500, and 405."}/>
    <Summary fr={fr} points={fr ? ["public/index.php amorce l’application.", "Les middlewares entourent le traitement.", "Le routeur utilise la méthode et le chemin.", "Response contient toujours le résultat HTTP final."] : ["public/index.php boots the application.", "Middleware surrounds processing.", "The router uses method and path.", "Response always contains the final HTTP result."]}/>
  </Frame>;

  if (lesson === "structure") return <Frame locale={locale} lesson={lesson} title={fr ? <>Pourquoi autant<br/><em>de dossiers ?</em></> : <>Why are there<br/><em>so many folders?</em></>} intro={fr ? "Un projet range ses fichiers comme une maison range ses objets. Découvrons chaque emplacement sans essayer de tout mémoriser." : "A project organizes its files like a home organizes its belongings. Let us discover each location without trying to memorize everything."}>
    <Analogy fr={fr} title={fr ? "La vitrine, l’atelier et les machines." : "The storefront, workshop, and machinery."}>{fr ? "public/ est la vitrine visible depuis la rue. src/ et routes/ sont l’atelier où votre équipe travaille. runtime/ contient les machines et pièces installées que l’on peut remettre en place. Un client doit voir la vitrine, jamais les plans privés ni les secrets rangés dans l’atelier." : "public/ is the storefront visible from the street. src/ and routes/ are the workshop where your team works. runtime/ contains installed machinery and parts that can be restored. A customer should see the storefront, never private plans or secrets stored in the workshop."}</Analogy>
    <section><h2>{fr ? "Commencez par seulement trois zones." : "Start with only three areas."}</h2><div className="zone-grid"><div><span>{fr ? "VISIBLE" : "VISIBLE"}</span><strong>public/</strong><p>{fr ? "Ce que le navigateur peut demander directement : le point d’entrée, les images et les fichiers publics." : "What the browser can request directly: the entry point, images, and public files."}</p></div><div><span>{fr ? "VOTRE TRAVAIL" : "YOUR WORK"}</span><strong>src/ · routes/</strong><p>{fr ? "Le code que vous écrivez pour définir les pages, les actions et les règles de votre application." : "The code you write to define your application's pages, actions, and rules."}</p></div><div><span>{fr ? "OUTILS INSTALLÉS" : "INSTALLED TOOLS"}</span><strong>runtime/</strong><p>{fr ? "Les éléments techniques préparés par AML. Vous les utilisez, mais vous n’y placez pas vos pages." : "Technical elements prepared by AML. You use them, but do not place your pages there."}</p></div></div></section>
    <section><h2>{fr ? "Fichier, dossier et extension : quelle différence ?" : "File, folder, and extension: what is the difference?"}</h2><p>{fr ? "Un fichier contient une information ou du code. Un dossier regroupe plusieurs fichiers. L’extension située après le point aide à reconnaître le contenu : .php pour du code PHP, .css pour la présentation visuelle, .json pour des informations structurées." : "A file contains information or code. A folder groups several files. The extension after the dot helps identify the content: .php for PHP code, .css for visual styling, and .json for structured information."}</p><div className="code-decoder"><div><code>HomeController.php</code><p>{fr ? "un fichier de code PHP" : "a PHP code file"}</p></div><div><code>home.css</code><p>{fr ? "un fichier qui décrit l’apparence" : "a file describing appearance"}</p></div><div><code>phpaml.json</code><p>{fr ? "un fichier de configuration lisible par AML" : "a configuration file read by AML"}</p></div></div></section>
    <section><h2>{fr ? "Les autres fichiers que vous rencontrerez souvent." : "Other files you will often encounter."}</h2><div className="file-guide"><FileGuide name="composer.json" badge={fr ? "CONFIGURATION" : "CONFIGURATION"} text={fr ? "Déclare les paquets PHP utilisés par le projet." : "Declares the PHP packages used by the project."}/><FileGuide name="composer.lock" badge={fr ? "VERSIONS" : "VERSIONS"} text={fr ? "Mémorise les versions exactes installées pour reproduire le même environnement." : "Records exact installed versions so the same environment can be reproduced."}/><FileGuide name=".env" badge={fr ? "SECRETS LOCAUX" : "LOCAL SECRETS"} text={fr ? "Contient les réglages propres à une machine. Ne le publiez pas s’il contient des secrets." : "Contains machine-specific settings. Do not publish it when it contains secrets."}/><FileGuide name="tests/" badge={fr ? "VÉRIFICATION" : "VERIFICATION"} text={fr ? "Contient du code qui vérifie automatiquement le comportement de l’application." : "Contains code that automatically checks application behavior."}/><FileGuide name="storage/" badge={fr ? "DONNÉES D’EXÉCUTION" : "RUNTIME DATA"} text={fr ? "Peut contenir journaux, cache ou fichiers produits pendant l’exécution, selon le projet." : "May contain logs, cache, or files produced while running, depending on the project."}/></div></section>
    <section><h2>{fr ? "Ce que vous modifiez, et ce que les outils gèrent." : "What you edit and what tools manage."}</h2><div className="good-bad"><div><span>{fr ? "VOUS MODIFIEZ" : "YOU EDIT"}</span><p>src/ · routes/ · public/ · tests/ · phpaml.json · composer.json</p></div><div><span>{fr ? "LES OUTILS GÈRENT GÉNÉRALEMENT" : "TOOLS GENERALLY MANAGE"}</span><p>runtime/ · vendor/ · composer.lock · cache</p></div></div><p>{fr ? "Cette séparation n’interdit pas toute modification avancée. Elle indique surtout où un débutant doit travailler sans risquer d’éditer des fichiers générés qui seront remplacés plus tard." : "This separation does not forbid all advanced changes. It mainly shows where a beginner should work without editing generated files that may later be replaced."}</p></section>
    <BeginnerQuestions fr={fr} items={fr ? [["Dois-je modifier runtime/ ?", "En général, non. AML installe et reconstruit ce dossier. Votre propre code vit surtout dans src/ et routes/."], ["Pourquoi public/ est-il spécial ?", "Le serveur Web l’expose au navigateur. Les secrets et le code interne doivent donc rester en dehors."], ["Puis-je créer mes propres dossiers dans src/ ?", "Oui. Quand l’application grandit, vous pouvez y organiser vos services, composants ou autres responsabilités."]] : [["Should I edit runtime/?", "Usually no. AML installs and rebuilds this folder. Your own code mainly lives in src/ and routes/."], ["Why is public/ special?", "The Web server exposes it to the browser. Secrets and internal code must stay outside it."], ["Can I create my own folders in src/?", "Yes. As the application grows, you can organize services, components, or other responsibilities there."]]}/>
    <section><h2>{fr ? "Un fichier indique à AML : « le projet commence ici »." : "One file tells AML: “the project starts here.”"}</h2><p>{fr ? "Ce fichier s’appelle phpaml.json. Il contient quelques informations sur le projet. Le mot manifeste désigne simplement cette fiche d’identité. Grâce à elle, AML retrouve le projet même si votre terminal se trouve dans un sous-dossier." : "This file is named phpaml.json. It contains a few details about the project. The word manifest simply means this identity card. It lets AML find the project even when your terminal is inside a subfolder."}</p><CodeBlock>{"project/\n├── phpaml.json        ← la fiche d’identité\n├── public/            ← ce que le Web peut voir\n├── routes/            ← les adresses connues\n├── src/               ← votre code\n└── runtime/           ← les outils installés"}</CodeBlock></section>
    <section><h2>{fr ? "Où placer un nouveau fichier ?" : "Where should a new file go?"}</h2><div className="placement-table"><Row left={fr ? "Une image accessible par URL" : "An image available by URL"} right="public/"/><Row left={fr ? "Une règle d’URL" : "A URL rule"} right="routes/"/><Row left={fr ? "Une action HTTP" : "An HTTP action"} right="src/controllers/"/><Row left={fr ? "Une règle métier ou donnée" : "A business rule or data object"} right="src/models/"/><Row left={fr ? "Une interface PHP" : "A PHP interface"} right="src/views/"/><Row left={fr ? "Une dépendance installée" : "An installed dependency"} right="runtime/"/></div></section>
    <section><h2>{fr ? "Appliquez la carte à notre bibliothèque." : "Apply the map to our library."}</h2><CodeBlock>{"public/images/covers/clean-code.jpg\nroutes/WebApp.php\nsrc/controllers/BookController.php\nsrc/models/Book.php\nsrc/views/books/show.php"}</CodeBlock><p>{fr ? "La couverture est publique parce que le navigateur doit la télécharger. La route connaît l’adresse. Le contrôleur orchestre la recherche. Book représente le livre. La vue sait comment afficher son titre et sa couverture. Aucun fichier ne remplit deux rôles à la fois." : "The cover is public because the browser must download it. The route knows the address. The controller orchestrates the lookup. Book represents the book. The view knows how to display its title and cover. No file performs two jobs."}</p></section>
    <Checkpoint fr={fr} question={fr ? "Pourquoi .env et src/ ne doivent-ils pas être placés sous public/ ?" : "Why should .env and src/ never be placed under public/?"} answer={fr ? "Parce que public/ est la zone exposée au serveur Web. Les secrets et le code interne doivent rester hors de cette racine." : "Because public/ is exposed to the Web server. Secrets and internal code must remain outside that root."}/>
    <MiniExercise fr={fr} prompt={fr ? "Placez ces fichiers : logo.svg, CheckoutController.php, User.php, Api.php et un fichier de cache reconstructible." : "Place these files: logo.svg, CheckoutController.php, User.php, Api.php, and a rebuildable cache file."} hint={fr ? "Utilisez public/, src/controllers/, src/models/, routes/ et runtime/." : "Use public/, src/controllers/, src/models/, routes/, and runtime/."}/>
    <Summary fr={fr} points={fr ? ["public/ est la seule racine Web.", "src/ et routes/ contiennent votre application.", "runtime/ peut être reconstruit.", "phpaml.json identifie et décrit le projet."] : ["public/ is the only Web root.", "src/ and routes/ contain your application.", "runtime/ can be rebuilt.", "phpaml.json identifies and describes the project."]}/>
  </Frame>;

  if (lesson === "mvc") return <Frame locale={locale} lesson={lesson} title={fr ? <>Pourquoi ne pas tout écrire<br/><em>dans un seul fichier ?</em></> : <>Why not write everything<br/><em>in one file?</em></>} intro={fr ? "On peut commencer dans un seul fichier. Mais lorsque le projet grandit, séparer les tâches aide à comprendre et modifier le code sans tout casser." : "You can begin with one file. But as the project grows, separating tasks helps you understand and change the code without breaking everything."}>
    <Analogy fr={fr} title={fr ? "Revenons au restaurant." : "Back to the restaurant."}>{fr ? "Le modèle est la cuisine : il connaît les produits et les règles. La vue est l’assiette : elle présente le résultat sans décider comment le cuire. Le contrôleur est le maître d’hôtel : il comprend la demande, consulte la cuisine et choisit la présentation adaptée. Si le maître d’hôtel cuisine, décore l’assiette et encaisse seul, le service devient vite impossible à faire évoluer." : "The model is the kitchen: it knows products and rules. The view is the plate: it presents the result without deciding how to cook it. The controller is the head waiter: it understands the request, consults the kitchen, and selects the appropriate presentation. If one person cooks, plates, and handles payment alone, the service quickly becomes impossible to evolve."}</Analogy>
    <section><h2>{fr ? "Trois tâches, trois noms." : "Three jobs, three names."}</h2><p>{fr ? "Les lettres MVC résument trois rôles. Ce ne sont pas trois programmes différents : ce sont trois façons de ranger le travail dans la même application." : "MVC summarizes three roles. They are not three separate programs: they are three ways to organize work inside the same application."}</p><div className="mvc-grid"><Concept title={fr ? "Modèle : ce que l’application connaît" : "Model: what the application knows"} mark="M">{fr ? "Le titre du livre, son auteur et la règle qui détermine s’il est disponible." : "The book title, its author, and the rule determining whether it is available."}</Concept><Concept title={fr ? "Vue : ce que la personne voit" : "View: what the person sees"} mark="V">{fr ? "Le titre, la couverture et le bouton affichés dans le navigateur." : "The title, cover, and button displayed in the browser."}</Concept><Concept title={fr ? "Contrôleur : ce qui relie les deux" : "Controller: what connects the two"} mark="C">{fr ? "Il reçoit le numéro 12, demande ce livre, puis choisit la page à afficher." : "It receives number 12, asks for that book, then selects the page to display."}</Concept></div></section>
    <section><h2>{fr ? "Exemple : afficher notre livre." : "Example: display our book."}</h2><CodeBlock>{"'GET /books/{id}' => [BookController::class, 'show']"}</CodeBlock><CodeBlock>{"public function show(Request $request): Response\n{\n    $book = $this->books->find((int) $request->attribute('id'));\n\n    if ($book === null) {\n        return Response::html('<h1>Not found</h1>', 404);\n    }\n\n    return $this->view('books/show.php', ['book' => $book]);\n}"}</CodeBlock><p>{fr ? "La route connaît l’adresse et l’action. Le contrôleur transforme l’identifiant, demande le livre au dépôt, traite l’absence puis choisit une vue. La vue reçoit déjà le livre à afficher." : "The route knows the address and action. The controller converts the identifier, asks the repository for the book, handles absence, then chooses a view. The view receives a book ready to display."}</p></section>
    <section><h2>{fr ? "Lisez le contrôleur ligne par ligne." : "Read the controller line by line."}</h2><div className="line-reading"><Line n="1" text={fr ? "show reçoit la requête déjà reconnue par le routeur." : "show receives the request already recognized by the router."}/><Line n="3" text={fr ? "L’identifiant de l’URL est converti en entier, puis transmis au dépôt." : "The URL identifier is converted to an integer, then passed to the repository."}/><Line n="5" text={fr ? "Le contrôleur prévoit le cas où le livre n’existe pas." : "The controller accounts for a missing book."}/><Line n="6" text={fr ? "Il choisit alors une réponse 404 explicite." : "It then selects an explicit 404 response."}/><Line n="9" text={fr ? "Sinon, il confie le livre à la vue; il ne fabrique pas le HTML lui-même." : "Otherwise, it gives the book to the view; it does not build HTML itself."}/></div></section>
    <section><h2>{fr ? "Reconnaître une responsabilité mal placée." : "Recognize a misplaced responsibility."}</h2><div className="chapter-one-troubles"><Trouble code={fr ? "SQL dans une vue" : "SQL inside a view"}>{fr ? "La vue connaît alors le stockage et devient difficile à tester." : "The view then knows storage details and becomes hard to test."}</Trouble><Trouble code={fr ? "HTML dans un modèle" : "HTML inside a model"}>{fr ? "Le modèle ne peut plus servir une API ou une autre présentation." : "The model can no longer serve an API or another presentation."}</Trouble><Trouble code={fr ? "Tout dans le contrôleur" : "Everything in the controller"}>{fr ? "Les règles métier deviennent longues, dupliquées et difficiles à réutiliser." : "Business rules become long, duplicated, and hard to reuse."}</Trouble></div></section>
    <section><h2>{fr ? "MVC n’est pas seul : trois rôles complémentaires." : "MVC is not alone: three complementary roles."}</h2><p>{fr ? "À mesure que l’application grandit, certains travaux ne rentrent proprement ni dans un modèle, ni dans une vue, ni dans un contrôleur. On leur donne alors un nom précis au lieu de grossir artificiellement les contrôleurs." : "As the application grows, some work fits neither a model, view, nor controller. It receives a precise name instead of making controllers artificially large."}</p><div className="useful-grid"><InfoCard title={fr ? "Service" : "Service"} text={fr ? "Exécute une opération métier qui combine plusieurs étapes, par exemple emprunter un livre et envoyer une confirmation." : "Performs a business operation combining several steps, such as borrowing a book and sending confirmation."}/><InfoCard title={fr ? "Dépôt" : "Repository"} text={fr ? "S’occupe de retrouver ou enregistrer les données sans exposer les détails de stockage au contrôleur." : "Retrieves or stores data without exposing storage details to the controller."}/><InfoCard title="Middleware" text={fr ? "Intervient avant ou après le contrôleur pour une règle commune : authentification, sécurité ou journalisation." : "Runs before or after the controller for a shared rule: authentication, security, or logging."}/><InfoCard title={fr ? "Validation" : "Validation"} text={fr ? "Vérifie que les informations reçues sont présentes et respectent le format attendu." : "Checks that received information exists and follows the expected format."}/></div></section>
    <section><h2>{fr ? "Une règle simple pour décider où écrire le code." : "A simple rule for deciding where code belongs."}</h2><div className="placement-table"><Row left={fr ? "Cela concerne l’adresse ou la méthode HTTP" : "It concerns the address or HTTP method"} right={fr ? "Route" : "Route"}/><Row left={fr ? "Cela organise la réponse à une demande" : "It organizes the answer to a request"} right={fr ? "Contrôleur" : "Controller"}/><Row left={fr ? "Cela décrit une donnée ou une règle métier" : "It describes data or a business rule"} right={fr ? "Modèle / service" : "Model / service"}/><Row left={fr ? "Cela choisit ce qui est affiché" : "It chooses what is displayed"} right={fr ? "Vue" : "View"}/><Row left={fr ? "Cela s’applique à de nombreuses requêtes" : "It applies to many requests"} right="Middleware"/></div></section>
    <section><h2>{fr ? "Pourquoi ne pas tout mettre dans un seul fichier ?" : "Why not put everything in one file?"}</h2><div className="good-bad"><div><span>{fr ? "AU DÉBUT" : "AT FIRST"}</span><p>{fr ? "Un fichier unique paraît plus rapide : lire l’URL, interroger la base et écrire le HTML au même endroit." : "One file feels faster: read the URL, query the database, and write HTML in one place."}</p></div><div><span>{fr ? "QUAND LE PROJET GRANDIT" : "AS THE PROJECT GROWS"}</span><p>{fr ? "Les mêmes règles sont recopiées, les tests exigent une page complète et une modification visuelle risque de toucher aux données. MVC paie son coût lorsque la deuxième fonctionnalité arrive." : "Rules get copied, tests require a whole page, and a visual change risks touching data. MVC pays off when the second feature arrives."}</p></div></div></section>
    <BeginnerQuestions fr={fr} items={fr ? [["MVC est-il obligatoire pour chaque petit programme ?", "Non. Un exercice très court peut tenir dans un seul fichier. La séparation devient utile lorsque le projet possède plusieurs pages ou règles."], ["Un modèle est-il forcément une table de base de données ?", "Non. Il représente surtout une donnée ou une règle du domaine. Il peut exister avant toute base de données."], ["Une vue contient-elle toujours du HTML ?", "Dans une application classique, souvent oui. Dans AML View, elle peut être décrite avec les composants PHP de PHPAML View."]] : [["Is MVC mandatory for every small program?", "No. A very short exercise can fit in one file. Separation becomes useful when a project has several pages or rules."], ["Is a model always a database table?", "No. It mainly represents domain data or a rule. It can exist before any database."], ["Does a view always contain HTML?", "In a classic application, often yes. In AML View, it can be described with PHPAML View's PHP components."]]}/>
    <Checkpoint fr={fr} question={fr ? "Qui doit vérifier qu’une remise commerciale est autorisée : la vue ou le domaine métier ?" : "Who should verify that a discount is allowed: the view or business domain?"} answer={fr ? "Le domaine métier, généralement dans un modèle ou un service. La vue se contente de présenter le résultat." : "The business domain, usually in a model or service. The view only presents the result."}/>
    <MiniExercise fr={fr} prompt={fr ? "Pour l’emprunt d’un livre, répartissez ces tâches : vérifier la disponibilité, lire l’identifiant de l’URL, afficher le bouton Emprunter." : "For borrowing a book, assign these tasks: check availability, read the URL identifier, display the Borrow button."} hint={fr ? "Modèle/service : disponibilité; contrôleur : identifiant; vue : bouton." : "Model/service: availability; controller: identifier; view: button."}/>
    <Summary fr={fr} points={fr ? ["Le modèle porte données et règles métier.", "La vue présente.", "Le contrôleur coordonne.", "Une bonne séparation permet de réutiliser la même logique en HTML ou JSON."] : ["The model owns data and business rules.", "The view presents.", "The controller coordinates.", "Good separation reuses the same logic for HTML or JSON."]}/>
  </Frame>;

  if (lesson === "variantes") return <Frame locale={locale} lesson={lesson} title={fr ? <>Une plateforme,<br/><em>quatre structures.</em></> : <>One platform,<br/><em>four structures.</em></>} intro={fr ? "PHPAML conserve les principes utiles, puis retire les dossiers qui n’ont aucun rôle dans le type de projet choisi." : "PHPAML keeps useful principles, then removes folders with no role in the selected project type."}>
    <section><h2>{fr ? "Choisissez selon la sortie attendue." : "Choose based on the expected output."}</h2><p>{fr ? "Ne choisissez pas une variante parce qu’elle paraît plus moderne. Demandez d’abord : qui utilisera le programme et quelle réponse doit-il recevoir ? Une page HTML, une interface réactive, des données JSON ou du texte dans un terminal conduisent naturellement à quatre structures différentes." : "Do not choose a variant because it sounds more modern. First ask: who will use the program, and what response should they receive? An HTML page, reactive interface, JSON data, or terminal text naturally lead to four different structures."}</p></section>
    <section><h2>{fr ? "Ce ne sont pas quatre langages différents." : "They are not four different languages."}</h2><p>{fr ? "Dans les quatre cas, vous écrivez du PHP. Ce qui change est la manière dont le programme est utilisé. Un visiteur peut recevoir une page complète, manipuler une interface réactive, une autre application peut demander des données, ou une personne peut lancer une commande dans le terminal." : "In all four cases, you write PHP. What changes is how the program is used. A visitor may receive a complete page, interact with a reactive interface, another application may request data, or a person may run a terminal command."}</p></section>
    <section><h2>{fr ? "Application classique" : "Classic application"}</h2><p>{fr ? "Elle reçoit une requête HTTP, utilise routes et contrôleurs, puis rend généralement une vue PHP sur le serveur." : "It receives an HTTP request, uses routes and controllers, then generally renders a PHP view on the server."}</p><CodeBlock>{"src/controllers/\nsrc/models/\nsrc/middleware/\nsrc/views/\nroutes/WebApp.php\npublic/index.php"}</CodeBlock></section>
    <section><h2>AML View</h2><p>{fr ? "Elle conserve le serveur PHPAML, mais ses pages et composants déclaratifs vivent sous src/views. Engine prend ensuite en charge les interactions frontend compilées." : "It keeps the PHPAML server, while declarative pages and components live under src/views. Engine then handles compiled frontend interactions."}</p><CodeBlock>{"src/views/pages/\nsrc/views/components/\nsrc/views/layouts/\nsrc/views/stylesheets/\nroutes/WebApp.php"}</CodeBlock></section>
    <section><h2>API</h2><p>{fr ? "Elle utilise HTTP, routes, contrôleurs et données, mais ne contient pas de couche de vues. Sa représentation finale est généralement JSON." : "It uses HTTP, routes, controllers, and data, but has no view layer. Its final representation is generally JSON."}</p><CodeBlock>{"src/controllers/\nsrc/requests/\nsrc/resources/\nsrc/repositories/\nsrc/routes/\npublic/index.php"}</CodeBlock></section>
    <section><h2>Console</h2><p>{fr ? "Elle n’a ni navigateur, ni requête HTTP, ni route. Program::main() reçoit les arguments du terminal et retourne un code de sortie." : "It has no browser, HTTP request, or route. Program::main() receives terminal arguments and returns an exit code."}</p><CodeBlock>{"src/Program.php\nsrc/\ntests/\nphpaml.json"}</CodeBlock></section>
    <section><h2>{fr ? "Le même catalogue, quatre usages." : "The same catalog, four uses."}</h2><div className="placement-table"><Row left={fr ? "Site de bibliothèque rendu sur le serveur" : "Server-rendered library website"} right="aml create"/><Row left={fr ? "Recherche réactive sans rechargement manuel" : "Reactive search without manual reload"} right="aml create-view"/><Row left={fr ? "Catalogue consommé par une application mobile" : "Catalog consumed by a mobile app"} right="aml create-api"/><Row left={fr ? "Import de 500 livres depuis un fichier" : "Import 500 books from a file"} right="aml create-console"/></div></section>
    <section><h2>{fr ? "Comparaison rapide." : "Quick comparison."}</h2><div className="variant-table" role="table"><div className="head" role="row"><strong>{fr ? "Projet" : "Project"}</strong><strong>{fr ? "Utilisé depuis" : "Used from"}</strong><strong>{fr ? "Résultat principal" : "Main result"}</strong><strong>{fr ? "Idéal pour" : "Ideal for"}</strong></div><VariantRow name={fr ? "Classique" : "Classic"} client={fr ? "Navigateur" : "Browser"} output="HTML" use={fr ? "Sites et formulaires rendus sur le serveur" : "Server-rendered websites and forms"}/><VariantRow name="View" client={fr ? "Navigateur" : "Browser"} output={fr ? "Interface réactive" : "Reactive interface"} use={fr ? "Tableaux de bord et applications interactives" : "Dashboards and interactive applications"}/><VariantRow name="API" client={fr ? "Mobile, site ou service" : "Mobile, website, or service"} output="JSON" use={fr ? "Partager des données entre applications" : "Sharing data between applications"}/><VariantRow name="Console" client={fr ? "Terminal" : "Terminal"} output={fr ? "Texte et code de sortie" : "Text and exit code"} use={fr ? "Automatisation, apprentissage et tâches planifiées" : "Automation, learning, and scheduled tasks"}/></div></section>
    <Checkpoint fr={fr} question={fr ? "Une API doit-elle obligatoirement avoir une vue ?" : "Must an API have a view?"} answer={fr ? "Non. Sa représentation finale est généralement JSON. Elle conserve routes, contrôleurs et données, mais n’a pas besoin d’une couche HTML." : "No. Its final representation is generally JSON. It keeps routes, controllers, and data, but does not need an HTML layer."}/>
    <MiniExercise fr={fr} prompt={fr ? "Choisissez une variante pour : un tableau de bord interactif, une commande de sauvegarde nocturne, un service mobile et un petit site institutionnel." : "Choose a variant for: an interactive dashboard, a nightly backup command, a mobile service, and a small institutional website."} hint={fr ? "View, Console, API, puis Classique." : "View, Console, API, then Classic."}/>
    <BeginnerQuestions fr={fr} items={fr ? [["Puis-je ajouter Data à ces projets ?", "Oui. Le module Data peut être ajouté lorsqu’un projet doit stocker et retrouver des informations."], ["Une application View possède-t-elle encore un serveur ?", "Oui. PHPAML et Engine collaborent pour produire l’interface et ses interactions."], ["Puis-je commencer simplement puis ajouter des modules ?", "Oui. Le type de départ donne une structure adaptée; les modules nécessaires peuvent ensuite être installés."]] : [["Can I add Data to these projects?", "Yes. The Data module can be added when a project must store and retrieve information."], ["Does a View application still have a server?", "Yes. PHPAML and Engine work together to produce the interface and its interactions."], ["Can I start simple and add modules later?", "Yes. The initial type provides a suitable structure; required modules can then be installed."]]}/>
    <Summary fr={fr} points={fr ? ["Classique rend des pages sur le serveur.", "View ajoute une interface déclarative réactive.", "API répond sans vue, généralement en JSON.", "Console exécute du PHP sans serveur HTTP."] : ["Classic renders pages on the server.", "View adds a declarative reactive interface.", "API responds without views, generally as JSON.", "Console runs PHP without an HTTP server."]}/>
  </Frame>;

  return <Frame locale={locale} lesson="atelier" title={fr ? <>Lire puis étendre<br/><em>un projet réel.</em></> : <>Read and extend<br/><em>a real project.</em></>} intro={fr ? "L’exercice final vérifie que vous savez suivre l’architecture avant d’écrire une nouvelle fonctionnalité." : "The final exercise verifies that you can follow the architecture before writing a new feature."}>
    <section><h2>{fr ? "La méthode avant le code." : "Method before code."}</h2><p>{fr ? "Ne commencez pas par créer des fichiers au hasard. Formulez d’abord la demande comme un trajet : le navigateur demande GET /about; une route doit reconnaître cette adresse; un contrôleur doit produire la réponse; le navigateur doit enfin recevoir un statut 200 et du HTML. Cette phrase devient votre plan de travail et votre plan de diagnostic." : "Do not begin by creating files at random. First express the request as a journey: the browser requests GET /about; a route must recognize that address; a controller must produce the response; the browser must finally receive status 200 and HTML. That sentence becomes both your implementation and diagnostic plan."}</p></section>
    <section className="chapter-one-exercise"><span>{fr ? "ATELIER FINAL" : "FINAL WORKSHOP"}</span><h2>{fr ? "Ajoutez une page À propos à une application classique." : "Add an About page to a classic application."}</h2><ol><li>{fr ? "Créez un projet nommé architecture-lab." : "Create a project named architecture-lab."}</li><li>{fr ? "Examinez phpaml.json, public/, routes/, src/ et runtime/." : "Inspect phpaml.json, public/, routes/, src/, and runtime/."}</li><li>{fr ? "Créez un contrôleur AboutController." : "Create an AboutController."}</li><li>{fr ? "Ajoutez GET /about dans routes/WebApp.php." : "Add GET /about to routes/WebApp.php."}</li><li>{fr ? "Retournez une réponse HTML simple, puis vérifiez-la dans le navigateur." : "Return a simple HTML response, then verify it in the browser."}</li></ol></section>
    <section><p className="chapter-one-kicker">{fr ? "CORRECTION GUIDÉE" : "GUIDED SOLUTION"}</p><h2>{fr ? "Construisez dans l’ordre de la requête." : "Build in request order."}</h2><CodeBlock>{"aml create architecture-lab\ncd architecture-lab\naml make:controller About\naml serve"}</CodeBlock><p>{fr ? "La commande crée le fichier du contrôleur sous src/controllers. Ajoutez ensuite la route dans routes/WebApp.php et reliez-la à AboutController::index. Cette route doit être chargée avant que le navigateur puisse atteindre l’action." : "The command creates the controller under src/controllers. Then add the route to routes/WebApp.php and connect it to AboutController::index. The route must be loaded before the browser can reach the action."}</p><CodeBlock>{"public function index(): Response\n{\n    return Response::html('<main><h1>About</h1><p>My first PHPAML page.</p></main>');\n}"}</CodeBlock><p>{fr ? "Ouvrez /about. Une réponse 200 prouve que le point d’entrée, le routeur, le contrôleur et la réponse fonctionnent ensemble. Une 404 indique généralement que la route n’est pas enregistrée; une 500 indique que le traitement a démarré puis échoué." : "Open /about. A 200 response proves that entry point, router, controller, and response work together. A 404 generally means the route is not registered; a 500 means processing started and then failed."}</p></section>
    <section><h2>{fr ? "Procédez par petites preuves." : "Work through small proofs."}</h2><ol className="request-steps"><Step n="1" title={fr ? "Prouver le démarrage" : "Prove startup"}>{fr ? "La page d’accueil doit encore répondre avant toute modification." : "The home page should still respond before any change."}</Step><Step n="2" title={fr ? "Prouver la route" : "Prove the route"}>{fr ? "Une 404 qui disparaît confirme que /about est maintenant reconnue." : "A disappearing 404 confirms that /about is now recognized."}</Step><Step n="3" title={fr ? "Prouver l’action" : "Prove the action"}>{fr ? "Un contenu très simple confirme que le contrôleur est appelé." : "Very simple content confirms the controller is called."}</Step><Step n="4" title={fr ? "Améliorer ensuite" : "Improve afterward"}>{fr ? "Ajoutez présentation et données seulement lorsque le trajet minimal fonctionne." : "Add presentation and data only after the minimal journey works."}</Step></ol></section>
    <section><h2>{fr ? "Si la page ne fonctionne pas, vérifiez dans cet ordre." : "If the page does not work, check in this order."}</h2><div className="diagnostic-list"><Diagnostic n="1" title={fr ? "Le serveur fonctionne-t-il ?" : "Is the server running?"} text={fr ? "Le terminal doit encore afficher que PHPAML écoute une adresse locale." : "The terminal should still show that PHPAML is listening on a local address."}/><Diagnostic n="2" title={fr ? "Utilisez-vous la bonne adresse ?" : "Are you using the correct address?"} text={fr ? "Vérifiez le port et le chemin /about dans le navigateur." : "Check the port and /about path in the browser."}/><Diagnostic n="3" title={fr ? "La route est-elle déclarée ?" : "Is the route declared?"} text={fr ? "Une erreur 404 signifie souvent que l’adresse n’est pas reliée au contrôleur." : "A 404 often means the address is not connected to the controller."}/><Diagnostic n="4" title={fr ? "La classe et la méthode existent-elles ?" : "Do the class and method exist?"} text={fr ? "Le nom AboutController et la méthode index doivent correspondre exactement à la route." : "The AboutController name and index method must exactly match the route."}/><Diagnostic n="5" title={fr ? "Que dit l’erreur détaillée ?" : "What does the detailed error say?"} text={fr ? "En développement, l’écran d’erreur et le terminal indiquent le fichier et la ligne à examiner." : "In development, the error screen and terminal identify the file and line to inspect."}/></div></section>
    <section><h2>{fr ? "Questions de compréhension" : "Knowledge check"}</h2><div className="knowledge-list"><Checkpoint fr={fr} question={fr ? "Pourquoi le contrôleur est-il placé dans src/ plutôt que public/ ?" : "Why is the controller under src/ rather than public/?"} answer={fr ? "Parce que le contrôleur est du code interne. Seul public/index.php doit être directement exposé au Web." : "Because the controller is internal code. Only public/index.php should be directly exposed to the Web."}/><Checkpoint fr={fr} question={fr ? "Pourquoi une route est-elle nécessaire ?" : "Why is a route required?"} answer={fr ? "Elle associe une méthode et un chemin HTTP à l’action qui doit les traiter." : "It connects an HTTP method and path to the action that handles them."}/></div></section>
    <Summary fr={fr} points={fr ? ["Vous savez suivre une requête complète.", "Vous savez distinguer code public, applicatif et reconstructible.", "Vous savez répartir modèle, vue et contrôleur.", "Vous pouvez maintenant aborder la migration d’un ancien projet."] : ["You can follow a complete request.", "You can distinguish public, application, and rebuildable code.", "You can distribute model, view, and controller responsibilities.", "You can now approach migration of an older project."]}/>
  </Frame>;
}

function Box({ n, title, text }: { n: string; title: string; text: string }) { return <div><span>{n}</span><strong>{title}</strong><small>{text}</small></div>; }
function Step({ n, title, children }: { n: string; title: string; children: React.ReactNode }) { return <li><span>{n}</span><div><strong>{title}</strong><p>{children}</p></div></li>; }
function Row({ left, right }: { left: string; right: string }) { return <div><span>{left}</span><code>{right}</code></div>; }
function Concept({ mark, title, children }: { mark: string; title: string; children: React.ReactNode }) { return <div><span>{mark}</span><strong>{title}</strong><p>{children}</p></div>; }
function Trouble({ code, children }: { code: string; children: React.ReactNode }) { return <div><code>{code}</code><p>{children}</p></div>; }
function Analogy({ fr, title, children }: { fr: boolean; title: string; children: React.ReactNode }) { return <aside className="chapter-two-analogy"><span>{fr ? "IMAGE MENTALE" : "MENTAL MODEL"}</span><div><h2>{title}</h2><p>{children}</p></div></aside>; }
function RunningExample({ fr }: { fr: boolean }) { return <aside className="chapter-two-story"><span>{fr ? "FIL CONDUCTEUR" : "RUNNING EXAMPLE"}</span><div><strong>{fr ? "La bibliothèque Fil Rouge" : "The Running Thread Library"}</strong><p>{fr ? "Tout au long du chapitre, nous suivrons une personne qui ouvre l’adresse /books/12 pour consulter le livre numéro 12. Nous découvrirons une étape à la fois ce qui se passe avant que la page apparaisse." : "Throughout this chapter, we will follow someone opening /books/12 to view book number 12. We will discover, one step at a time, what happens before the page appears."}</p></div></aside>; }
function Vocabulary({ fr, items }: { fr: boolean; items: [string, string][] }) { return <section className="chapter-two-vocabulary"><p className="chapter-one-kicker">{fr ? "LES MOTS À CONNAÎTRE" : "WORDS TO KNOW"}</p><h2>{fr ? "Un petit dictionnaire avant de continuer" : "A small dictionary before continuing"}</h2><dl>{items.map(([term, meaning]) => <div key={term}><dt>{term}</dt><dd>{meaning}</dd></div>)}</dl></section>; }
function BeginnerQuestions({ fr, items }: { fr: boolean; items: [string, string][] }) { return <section className="chapter-two-questions"><p className="chapter-one-kicker">{fr ? "QUESTIONS DE DÉBUTANT" : "BEGINNER QUESTIONS"}</p><h2>{fr ? "Vous vous demandez peut-être…" : "You may be wondering…"}</h2><div>{items.map(([question, answer]) => <details key={question}><summary>{question}</summary><p>{answer}</p></details>)}</div></section>; }
function MiniExercise({ fr, prompt, hint }: { fr: boolean; prompt: string; hint: string }) { return <section className="chapter-two-exercise"><p className="chapter-one-kicker">{fr ? "À VOUS DE JOUER" : "YOUR TURN"}</p><h2>{prompt}</h2><details><summary>{fr ? "Voir un indice" : "Show a hint"}</summary><p>{hint}</p></details></section>; }
function Line({ n, text }: { n: string; text: string }) { return <div><code>{n}</code><p>{text}</p></div>; }
function InfoCard({ title, text }: { title: string; text: string }) { return <div><strong>{title}</strong><p>{text}</p></div>; }
function FileGuide({ name, badge, text }: { name: string; badge: string; text: string }) { return <div><code>{name}</code><span>{badge}</span><p>{text}</p></div>; }
function VariantRow({ name, client, output, use }: { name: string; client: string; output: string; use: string }) { return <div role="row"><strong>{name}</strong><span>{client}</span><code>{output}</code><span>{use}</span></div>; }
function Diagnostic({ n, title, text }: { n: string; title: string; text: string }) { return <div><span>{n}</span><div><strong>{title}</strong><p>{text}</p></div></div>; }
function Summary({ fr, points }: { fr: boolean; points: string[] }) { return <section className="chapter-one-summary"><p className="chapter-one-kicker">{fr ? "EN RÉSUMÉ" : "SUMMARY"}</p><h2>{fr ? "Ce qu’il faut retenir" : "What to remember"}</h2><ul>{points.map((point) => <li key={point}>{point}</li>)}</ul></section>; }
function Checkpoint({ fr, question, answer }: { fr: boolean; question: string; answer: string }) { return <section className="chapter-one-checkpoint"><p className="chapter-one-kicker">{fr ? "VÉRIFIEZ VOTRE COMPRÉHENSION" : "CHECK YOUR UNDERSTANDING"}</p><h2>{question}</h2><details><summary>{fr ? "Afficher la réponse" : "Show the answer"}</summary><p>{answer}</p></details></section>; }
